CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.ai_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'My business', timezone text NOT NULL DEFAULT 'Africa/Lagos', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_workspaces TO authenticated;
GRANT ALL ON public.ai_workspaces TO service_role;
ALTER TABLE public.ai_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_owner_read ON public.ai_workspaces FOR SELECT TO authenticated USING (owner_id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.ai_workspaces(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner', UNIQUE(user_id, workspace_id));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.ai_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.ai_workspaces(id) ON DELETE CASCADE, environment text NOT NULL CHECK (environment IN ('test','live')), title text NOT NULL DEFAULT 'New conversation', pinned boolean NOT NULL DEFAULT false, currency text NOT NULL DEFAULT 'NGN', period text NOT NULL DEFAULT 'Last 30 days', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_threads TO authenticated;
GRANT ALL ON public.ai_threads TO service_role;
ALTER TABLE public.ai_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY threads_own ON public.ai_threads FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.ai_workspaces w WHERE w.id = workspace_id AND w.owner_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.ai_workspaces w WHERE w.id = workspace_id AND w.owner_id = auth.uid()));
CREATE INDEX ai_threads_scope ON public.ai_threads(user_id, workspace_id, environment, updated_at DESC);
CREATE TABLE public.ai_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.ai_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, sdk_id text NOT NULL, role text NOT NULL CHECK (role IN ('user','assistant')), parts jsonb NOT NULL DEFAULT '[]'::jsonb, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id, sdk_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_messages TO authenticated;
GRANT ALL ON public.ai_messages TO service_role;
ALTER TABLE public.ai_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own ON public.ai_messages FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.ai_threads t WHERE t.id = thread_id AND t.user_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.ai_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE INDEX ai_messages_thread ON public.ai_messages(thread_id, created_at);
CREATE TABLE public.ai_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, thread_id uuid NOT NULL REFERENCES public.ai_threads(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'started', input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, safe_error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_runs TO authenticated;
GRANT ALL ON public.ai_runs TO service_role;
ALTER TABLE public.ai_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY runs_own ON public.ai_runs FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.ai_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, thread_id uuid REFERENCES public.ai_threads(id) ON DELETE CASCADE, event text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_audit TO authenticated;
GRANT ALL ON public.ai_audit TO service_role;
ALTER TABLE public.ai_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_own ON public.ai_audit FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.ai_access_state (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, blocked boolean NOT NULL DEFAULT false, status integer, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_access_state TO authenticated;
GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_state_own ON public.ai_access_state FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.create_griv_ai_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE workspace uuid; BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name', '')); INSERT INTO public.ai_workspaces(owner_id) VALUES (NEW.id) RETURNING id INTO workspace; INSERT INTO public.user_roles(user_id, workspace_id, role) VALUES (NEW.id, workspace, 'owner'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_griv_ai_account() FROM PUBLIC;
CREATE TRIGGER griv_ai_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_griv_ai_account();